-- Source: schema.sql
-- ============================================================================
-- Meera schema
-- Run this once in the Supabase SQL editor (Dashboard -> SQL Editor -> New query).
-- Safe to re-run: everything is idempotent.
-- ============================================================================

create extension if not exists citext;
create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  username      citext unique not null check (username ~ '^[a-z0-9_.]{3,20}$'),
  display_name  text not null default '',
  avatar_seed   text not null default 'default',
  avatar_hue    int  not null default 45,
  created_at    timestamptz not null default now()
);

-- Auth uses username@meera.local synthetic emails; this trigger mirrors the
-- chosen username (passed as user metadata) into a real profile row.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, username, display_name, avatar_hue)
  values (
    new.id,
    lower(coalesce(new.raw_user_meta_data->>'username', 'user' || substr(new.id::text, 1, 8))),
    coalesce(new.raw_user_meta_data->>'display_name', ''),
    (abs(hashtext(new.id::text)) % 360)
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- friendships  (one row per pair, user_a < user_b enforced)
-- ---------------------------------------------------------------------------
create table if not exists public.friendships (
  id           uuid primary key default gen_random_uuid(),
  user_a       uuid not null references public.profiles(id) on delete cascade,
  user_b       uuid not null references public.profiles(id) on delete cascade,
  requested_by uuid not null references public.profiles(id) on delete cascade,
  status       text not null default 'pending' check (status in ('pending','accepted','blocked')),
  created_at   timestamptz not null default now(),
  constraint ordered_pair check (user_a < user_b),
  unique (user_a, user_b)
);

-- Canonical pair helper so callers never worry about ordering.
create or replace function public.pair_key(u1 uuid, u2 uuid)
returns uuid[] language sql immutable as $$
  select case when u1 < u2 then array[u1, u2] else array[u2, u1] end;
$$;

-- ---------------------------------------------------------------------------
-- messages  (chats and snaps share one table; `kind` distinguishes them)
-- ---------------------------------------------------------------------------
create table if not exists public.messages (
  id              uuid primary key default gen_random_uuid(),
  user_a          uuid not null references public.profiles(id) on delete cascade,
  user_b          uuid not null references public.profiles(id) on delete cascade,
  sender_id       uuid not null references public.profiles(id) on delete cascade,
  kind            text not null check (kind in ('chat','snap')),
  body            text,
  media_path      text,
  media_type      text check (media_type in ('image','video')),
  has_audio       boolean not null default false,
  view_seconds    int,                       -- null = infinity ("no limit")
  created_at      timestamptz not null default now(),
  delivered_at    timestamptz,
  opened_at       timestamptz,
  replayed_at     timestamptz,
  screenshot_at   timestamptz,
  saved_by        uuid[] not null default '{}',
  cleared_at      timestamptz,               -- ephemeral deletion (viewed / 24h)
  unsent_at       timestamptz,               -- sender pressed "unsend"
  constraint ordered_pair_msg check (user_a < user_b)
);

create index if not exists messages_pair_idx on public.messages (user_a, user_b, created_at desc);
create index if not exists messages_sender_idx on public.messages (sender_id);

-- ---------------------------------------------------------------------------
-- streaks  (one row per friend pair)
-- ---------------------------------------------------------------------------
create table if not exists public.streaks (
  user_a          uuid not null references public.profiles(id) on delete cascade,
  user_b          uuid not null references public.profiles(id) on delete cascade,
  count           int  not null default 0,
  -- last snap sent by each side; a streak day requires BOTH within 24h
  last_snap_a     timestamptz,
  last_snap_b     timestamptz,
  last_increment  timestamptz,
  primary key (user_a, user_b),
  constraint ordered_pair_streak check (user_a < user_b)
);

-- ---------------------------------------------------------------------------
-- stories  (48h / 2-day expiry)
-- ---------------------------------------------------------------------------
create table if not exists public.stories (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles(id) on delete cascade,
  media_path   text not null,
  media_type   text not null default 'image' check (media_type in ('image','video')),
  caption      text,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '48 hours'
);
create index if not exists stories_user_idx on public.stories (user_id, created_at desc);
create index if not exists stories_expiry_idx on public.stories (expires_at);

create table if not exists public.story_views (
  story_id      uuid not null references public.stories(id) on delete cascade,
  viewer_id     uuid not null references public.profiles(id) on delete cascade,
  viewed_at     timestamptz not null default now(),
  screenshot_at timestamptz,
  primary key (story_id, viewer_id)
);

-- ============================================================================
-- Streak logic
-- ============================================================================
-- Snapchat rule: a streak needs BOTH friends to send a snap (not a chat) to
-- each other within each 24-hour window. Sending twice in a row does not
-- advance it. The streak dies when either side lets 24h lapse.
create or replace function public.bump_streak()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  s public.streaks%rowtype;
  now_ts timestamptz := now();
  sender_is_a boolean := (new.sender_id = new.user_a);
  a_ts timestamptz;
  b_ts timestamptz;
begin
  if new.kind <> 'snap' then
    return new;
  end if;

  insert into public.streaks (user_a, user_b)
  values (new.user_a, new.user_b)
  on conflict (user_a, user_b) do nothing;

  select * into s from public.streaks
   where user_a = new.user_a and user_b = new.user_b for update;

  -- If either side has gone silent for more than 24h, the streak is already dead.
  if s.count > 0 and (
       s.last_snap_a is null or s.last_snap_b is null
       or s.last_snap_a < now_ts - interval '24 hours'
       or s.last_snap_b < now_ts - interval '24 hours') then
    s.count := 0;
    s.last_increment := null;
  end if;

  a_ts := case when sender_is_a then now_ts else s.last_snap_a end;
  b_ts := case when sender_is_a then s.last_snap_b else now_ts end;

  -- Both sides active within 24h, and we haven't already counted this window.
  if a_ts is not null and b_ts is not null
     and a_ts > now_ts - interval '24 hours'
     and b_ts > now_ts - interval '24 hours'
     and (s.last_increment is null or s.last_increment < now_ts - interval '20 hours')
  then
    s.count := greatest(s.count, 0) + 1;
    s.last_increment := now_ts;
  end if;

  update public.streaks
     set count = s.count,
         last_snap_a = a_ts,
         last_snap_b = b_ts,
         last_increment = s.last_increment
   where user_a = new.user_a and user_b = new.user_b;

  return new;
end;
$$;

drop trigger if exists on_message_streak on public.messages;
create trigger on_message_streak
  after insert on public.messages
  for each row execute function public.bump_streak();

-- ============================================================================
-- Row Level Security
-- ============================================================================
alter table public.profiles    enable row level security;
alter table public.friendships enable row level security;
alter table public.messages    enable row level security;
alter table public.streaks     enable row level security;
alter table public.stories     enable row level security;
alter table public.story_views enable row level security;

-- profiles: everyone signed in can look up profiles (needed to add by username)
drop policy if exists profiles_read on public.profiles;
create policy profiles_read on public.profiles
  for select to authenticated using (true);

drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own on public.profiles
  for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- friendships: only the two parties can see or touch the row
drop policy if exists friendships_rw on public.friendships;
create policy friendships_rw on public.friendships
  for all to authenticated
  using (auth.uid() in (user_a, user_b))
  with check (auth.uid() in (user_a, user_b));

-- messages: only the two parties; only the sender may create as themselves
drop policy if exists messages_read on public.messages;
create policy messages_read on public.messages
  for select to authenticated using (auth.uid() in (user_a, user_b));

drop policy if exists messages_insert on public.messages;
create policy messages_insert on public.messages
  for insert to authenticated
  with check (auth.uid() = sender_id and auth.uid() in (user_a, user_b));

-- Both parties may update (recipient marks opened/screenshot, sender unsends).
drop policy if exists messages_update on public.messages;
create policy messages_update on public.messages
  for update to authenticated using (auth.uid() in (user_a, user_b));

drop policy if exists streaks_read on public.streaks;
create policy streaks_read on public.streaks
  for select to authenticated using (auth.uid() in (user_a, user_b));

-- stories: readable by accepted friends, writable only by the author
drop policy if exists stories_read on public.stories;
create policy stories_read on public.stories
  for select to authenticated using (
    user_id = auth.uid()
    or exists (
      select 1 from public.friendships f
       where f.status = 'accepted'
         and array[f.user_a, f.user_b] = public.pair_key(auth.uid(), stories.user_id)
    )
  );

drop policy if exists stories_write on public.stories;
create policy stories_write on public.stories
  for insert to authenticated with check (user_id = auth.uid());

drop policy if exists stories_delete on public.stories;
create policy stories_delete on public.stories
  for delete to authenticated using (user_id = auth.uid());

-- story_views: viewer writes their own; author reads all views of their story
drop policy if exists story_views_insert on public.story_views;
create policy story_views_insert on public.story_views
  for insert to authenticated with check (viewer_id = auth.uid());

drop policy if exists story_views_update on public.story_views;
create policy story_views_update on public.story_views
  for update to authenticated using (viewer_id = auth.uid());

drop policy if exists story_views_read on public.story_views;
create policy story_views_read on public.story_views
  for select to authenticated using (
    viewer_id = auth.uid()
    or exists (select 1 from public.stories s
                where s.id = story_views.story_id and s.user_id = auth.uid())
  );

-- ============================================================================
-- Table privileges
-- ============================================================================
-- RLS decides WHICH ROWS a role may touch. It does not grant access to the
-- table itself — that is a separate, older Postgres mechanism. Without these
-- GRANTs every query fails with "42501: permission denied", no matter how
-- permissive the policies are.
--
-- Granting broadly to `authenticated` is safe here precisely because every
-- table above has RLS enabled: the policies remain the real gate, and the
-- grants are only what lets the policies get evaluated at all. Privileges are
-- still kept to what each table's policies actually allow.
grant usage on schema public to anon, authenticated;

grant select, update            on public.profiles    to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
grant select, insert, update    on public.messages    to authenticated;
grant select                    on public.streaks     to authenticated;
grant select, insert, delete    on public.stories     to authenticated;
grant select, insert, update    on public.story_views to authenticated;

-- ============================================================================
-- Realtime
-- ============================================================================
alter publication supabase_realtime add table public.messages;
alter publication supabase_realtime add table public.friendships;
alter publication supabase_realtime add table public.stories;
alter publication supabase_realtime add table public.streaks;

-- ============================================================================
-- Storage bucket for snap + story media
-- ============================================================================
insert into storage.buckets (id, name, public)
values ('media', 'media', false)
on conflict (id) do nothing;

-- Any authenticated user may upload under their own uid prefix: media/<uid>/<file>
drop policy if exists media_upload on storage.objects;
create policy media_upload on storage.objects
  for insert to authenticated
  with check (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);

-- Reads are brokered by signed URLs generated server-side by the client SDK;
-- allow authenticated reads within the bucket.
drop policy if exists media_read on storage.objects;
create policy media_read on storage.objects
  for select to authenticated using (bucket_id = 'media');

drop policy if exists media_delete on storage.objects;
create policy media_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);


-- Source: hardening.sql
-- ============================================================================
-- Meera security hardening — apply once, after schema.sql.
-- Addresses the audit findings. Idempotent.
--
-- Core principle codified here: RLS gates ROWS, not COLUMNS. "Which columns may
-- change" is enforced with column-level GRANT; "write-once / monotonic" is
-- enforced with BEFORE triggers (WITH CHECK cannot see OLD). Policies alone are
-- not sufficient and several original ones wrongly assumed they were.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- CRITICAL-1 — storage reads were open to every authenticated user.
-- Scope them to: the owner, a party to the message, or the audience of a story.
-- ---------------------------------------------------------------------------
drop policy if exists media_read on storage.objects;
create policy media_read on storage.objects
  for select to authenticated using (
    bucket_id = 'media' and (
      (storage.foldername(name))[1] = auth.uid()::text
      or exists (
        select 1 from public.messages m
         where m.media_path = storage.objects.name
           and auth.uid() in (m.user_a, m.user_b))
      or exists (
        select 1 from public.stories s
         where s.media_path = storage.objects.name
           and (s.user_id = auth.uid()
                or exists (select 1 from public.friendships f
                            where f.status = 'accepted'
                              and array[f.user_a, f.user_b]
                                  = public.pair_key(auth.uid(), s.user_id))))
    )
  );
create index if not exists messages_media_path_idx on public.messages (media_path);
create index if not exists stories_media_path_idx  on public.stories  (media_path);

-- ---------------------------------------------------------------------------
-- CRITICAL-2 — message columns were fully mutable by either party.
-- Freeze content columns via column GRANTs; guard monotonic fields via trigger.
-- ---------------------------------------------------------------------------
revoke insert on public.messages from authenticated;
grant insert (user_a, user_b, sender_id, kind, body, media_path, media_type,
              has_audio, view_seconds, delivered_at) on public.messages to authenticated;

revoke update on public.messages from authenticated;
grant update (opened_at, replayed_at, screenshot_at, saved_by, cleared_at, unsent_at)
  on public.messages to authenticated;

create or replace function public.guard_message_update()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- receipt stamps are write-once
  if old.opened_at     is not null and new.opened_at     is distinct from old.opened_at     then raise exception 'opened_at is immutable'; end if;
  if old.screenshot_at is not null and new.screenshot_at is distinct from old.screenshot_at then raise exception 'screenshot_at is immutable'; end if;
  if old.replayed_at   is not null and new.replayed_at   is distinct from old.replayed_at   then raise exception 'replayed_at is immutable'; end if;
  -- unsend is one-way and sender-only
  if old.unsent_at is not null and new.unsent_at is distinct from old.unsent_at then raise exception 'message already unsent'; end if;
  if new.unsent_at is not null and old.unsent_at is null and old.sender_id <> auth.uid() then
    raise exception 'only the sender may unsend'; end if;
  -- saved_by: caller may only add or remove their OWN uid
  if new.saved_by is distinct from old.saved_by then
    if (select coalesce(array_agg(x order by x), '{}') from unnest(new.saved_by) x where x <> auth.uid())
       is distinct from
       (select coalesce(array_agg(x order by x), '{}') from unnest(old.saved_by) x where x <> auth.uid())
    then raise exception 'may only save/unsave for yourself'; end if;
  end if;
  return new;
end $$;

drop trigger if exists on_message_update on public.messages;
create trigger on_message_update before update on public.messages
  for each row execute function public.guard_message_update();

-- ---------------------------------------------------------------------------
-- HIGH-1 — friendships: split FOR ALL into a real state machine so nobody can
-- self-accept, forge requested_by, or silently re-open a blocked pair.
-- ---------------------------------------------------------------------------
alter table public.friendships add column if not exists blocked_by uuid references public.profiles(id);

drop policy if exists friendships_rw on public.friendships;

create policy friendships_read on public.friendships
  for select to authenticated using (auth.uid() in (user_a, user_b));

create policy friendships_insert on public.friendships
  for insert to authenticated
  with check (auth.uid() in (user_a, user_b)
              and requested_by = auth.uid()
              and status = 'pending');

create policy friendships_update on public.friendships
  for update to authenticated
  using  (auth.uid() in (user_a, user_b))
  with check (auth.uid() in (user_a, user_b));

create policy friendships_delete on public.friendships
  for delete to authenticated using (auth.uid() in (user_a, user_b));

create or replace function public.guard_friendship_update()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.requested_by <> old.requested_by then raise exception 'requested_by is immutable'; end if;
  if new.user_a <> old.user_a or new.user_b <> old.user_b then raise exception 'pair is immutable'; end if;
  -- only the RECIPIENT of a request may accept it
  if new.status = 'accepted' and old.status <> 'accepted' and old.requested_by = auth.uid() then
    raise exception 'cannot accept your own request'; end if;
  -- a blocked pair may only be unblocked by whoever blocked it
  if old.status = 'blocked' and new.status <> 'blocked'
     and old.blocked_by is distinct from auth.uid() then
    raise exception 'only the blocker may unblock'; end if;
  return new;
end $$;

drop trigger if exists on_friendship_update on public.friendships;
create trigger on_friendship_update before update on public.friendships
  for each row execute function public.guard_friendship_update();

-- messages may only flow between accepted friends
drop policy if exists messages_insert on public.messages;
create policy messages_insert on public.messages
  for insert to authenticated
  with check (
    auth.uid() = sender_id and auth.uid() in (user_a, user_b)
    and exists (select 1 from public.friendships f
                 where f.user_a = messages.user_a and f.user_b = messages.user_b
                   and f.status = 'accepted')
  );

-- ---------------------------------------------------------------------------
-- HIGH-2 — derive username from the (unique) email, never trust client
-- metadata; freeze the username column.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare uname citext := lower(split_part(new.email, '@', 1));
begin
  if uname !~ '^[a-z0-9_.]{3,20}$' then
    raise exception 'invalid username %', uname using errcode = '23514';
  end if;
  insert into public.profiles (id, username, display_name, avatar_hue)
  values (new.id, uname,
          coalesce(new.raw_user_meta_data->>'display_name', ''),
          (abs(hashtext(new.id::text)) % 360))
  on conflict (id) do nothing;
  return new;
end $$;

revoke update on public.profiles from authenticated;
grant update (display_name, avatar_seed, avatar_hue) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- MED-1 — profiles were world-readable (full user enumeration, and step 1 of
-- the storage exploit). Restrict to self + known relationships; route username
-- discovery through a definer point-lookup.
-- ---------------------------------------------------------------------------
drop policy if exists profiles_read on public.profiles;
create policy profiles_read on public.profiles
  for select to authenticated using (
    id = auth.uid()
    or exists (select 1 from public.friendships f
                where array[f.user_a, f.user_b] = public.pair_key(auth.uid(), profiles.id))
  );

create or replace function public.lookup_username(u citext)
returns table (id uuid, username citext, display_name text, avatar_seed text, avatar_hue int)
language sql stable security definer set search_path = public as $$
  select p.id, p.username, p.display_name, p.avatar_seed, p.avatar_hue
    from public.profiles p where p.username = u;
$$;
revoke all on function public.lookup_username(citext) from public;
grant execute on function public.lookup_username(citext) to authenticated;

-- ---------------------------------------------------------------------------
-- HIGH-3 / MED-3 — stories: freeze expiry/author at insert; make reads respect
-- expiry rather than relying on a client-side filter.
-- ---------------------------------------------------------------------------
revoke insert on public.stories from authenticated;
grant insert (user_id, media_path, media_type, caption) on public.stories to authenticated;

drop policy if exists stories_read on public.stories;
create policy stories_read on public.stories
  for select to authenticated using (
    (expires_at > now() or user_id = auth.uid())
    and (user_id = auth.uid()
         or exists (select 1 from public.friendships f
                     where f.status = 'accepted'
                       and array[f.user_a, f.user_b] = public.pair_key(auth.uid(), stories.user_id)))
  );

-- ---------------------------------------------------------------------------
-- LOW-1 — story_views: viewer may only stamp their own screenshot flag, and
-- only on a story that exists.
-- ---------------------------------------------------------------------------
drop policy if exists story_views_insert on public.story_views;
create policy story_views_insert on public.story_views
  for insert to authenticated
  with check (viewer_id = auth.uid()
              and exists (select 1 from public.stories s where s.id = story_id));

revoke update on public.story_views from authenticated;
grant update (screenshot_at) on public.story_views to authenticated;

-- ---------------------------------------------------------------------------
-- MED-2 — streak: the increment guard used 20h against a 24h window, ratcheting
-- the clock backwards and letting one side inflate the count. Match to 24h and
-- require both sides to have acted within the current window.
-- ---------------------------------------------------------------------------
create or replace function public.bump_streak()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  s public.streaks%rowtype;
  now_ts timestamptz := now();
  sender_is_a boolean := (new.sender_id = new.user_a);
  a_ts timestamptz;
  b_ts timestamptz;
begin
  if new.kind <> 'snap' then return new; end if;

  insert into public.streaks (user_a, user_b) values (new.user_a, new.user_b)
    on conflict (user_a, user_b) do nothing;
  select * into s from public.streaks
   where user_a = new.user_a and user_b = new.user_b for update;
  if not found then return new; end if;

  if s.count > 0 and (
       s.last_snap_a is null or s.last_snap_b is null
       or s.last_snap_a < now_ts - interval '24 hours'
       or s.last_snap_b < now_ts - interval '24 hours') then
    s.count := 0; s.last_increment := null;
  end if;

  a_ts := case when sender_is_a then now_ts else s.last_snap_a end;
  b_ts := case when sender_is_a then s.last_snap_b else now_ts end;

  if a_ts is not null and b_ts is not null
     and a_ts > now_ts - interval '24 hours'
     and b_ts > now_ts - interval '24 hours'
     and (s.last_increment is null
          or (least(a_ts, b_ts) > s.last_increment
              and s.last_increment < now_ts - interval '24 hours'))
  then
    s.count := greatest(s.count, 0) + 1;
    s.last_increment := now_ts;
  end if;

  update public.streaks
     set count = s.count, last_snap_a = a_ts, last_snap_b = b_ts,
         last_increment = s.last_increment
   where user_a = new.user_a and user_b = new.user_b;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- HIGH-3 — server-side purge of expired content (ephemerality was never
-- enforced; everything was retained forever). Scheduled if pg_cron is present.
-- ---------------------------------------------------------------------------
create or replace function public.purge_expired()
returns void language plpgsql security definer set search_path = public as $$
begin
  with gone as (
    delete from public.messages
     where saved_by = '{}'
       and ((opened_at is not null and opened_at < now() - interval '24 hours')
            or (opened_at is null and created_at < now() - interval '31 days')
            or (unsent_at is not null and unsent_at < now() - interval '1 hour'))
    returning media_path)
  delete from storage.objects
   where bucket_id = 'media' and name in (select media_path from gone where media_path is not null);

  with dead as (delete from public.stories where expires_at < now() returning media_path)
  delete from storage.objects
   where bucket_id = 'media' and name in (select media_path from dead where media_path is not null);
end $$;

do $$
begin
  perform cron.schedule('meera-purge-expired', '*/15 * * * *', 'select public.purge_expired()');
exception when undefined_function or undefined_table or invalid_schema_name then
  raise notice 'pg_cron not enabled; run select public.purge_expired() from a scheduled job manually';
end $$;

-- ---------------------------------------------------------------------------
-- LOW-2/3/4 — missing indexes and constraints.
-- ---------------------------------------------------------------------------
create index if not exists friendships_user_b_idx on public.friendships (user_b);
create index if not exists streaks_user_b_idx      on public.streaks     (user_b);
create index if not exists friendships_pair_status_idx on public.friendships (status, user_a, user_b);

-- ADD CONSTRAINT has no IF NOT EXISTS form, so guard each one.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'snap_has_media') then
    alter table public.messages add constraint snap_has_media
      check (kind <> 'snap' or media_path is not null);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'view_seconds_sane') then
    alter table public.messages add constraint view_seconds_sane
      check (view_seconds is null or view_seconds between 1 and 60);
  end if;
end $$;


-- Source: chat_vanish.sql
-- ============================================================================
-- Snapchat "Delete after viewing" — the default chat behaviour.
-- A chat disappears for a viewer once they have seen it AND left the
-- conversation. Per-user, so it never vanishes for the other party before they
-- have read it. Saved messages are exempt.
-- ============================================================================

alter table public.messages add column if not exists cleared_by uuid[] not null default '{}';
grant update (cleared_by) on public.messages to authenticated;

-- Called when a user leaves a conversation: marks every chat they have already
-- opened as cleared for them alone. One statement, server-side, so a client
-- cannot clear on someone else's behalf (auth.uid() is the only id written).
create or replace function public.clear_viewed_chats(other uuid)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set cleared_by = array_append(cleared_by, auth.uid())
   where kind = 'chat'
     and array[user_a, user_b] = public.pair_key(auth.uid(), other)
     and opened_at is not null
     and saved_by = '{}'
     and not (auth.uid() = any(cleared_by));
$$;
revoke all on function public.clear_viewed_chats(uuid) from public;
grant execute on function public.clear_viewed_chats(uuid) to authenticated;

-- Let the existing update guard treat cleared_by like saved_by: a caller may
-- only add or remove their OWN id.
create or replace function public.guard_message_update()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if old.opened_at     is not null and new.opened_at     is distinct from old.opened_at     then raise exception 'opened_at is immutable'; end if;
  if old.screenshot_at is not null and new.screenshot_at is distinct from old.screenshot_at then raise exception 'screenshot_at is immutable'; end if;
  if old.replayed_at   is not null and new.replayed_at   is distinct from old.replayed_at   then raise exception 'replayed_at is immutable'; end if;
  if old.unsent_at is not null and new.unsent_at is distinct from old.unsent_at then raise exception 'message already unsent'; end if;
  if new.unsent_at is not null and old.unsent_at is null and old.sender_id <> auth.uid() then
    raise exception 'only the sender may unsend'; end if;
  if new.saved_by is distinct from old.saved_by then
    if (select coalesce(array_agg(x order by x), '{}') from unnest(new.saved_by) x where x <> auth.uid())
       is distinct from
       (select coalesce(array_agg(x order by x), '{}') from unnest(old.saved_by) x where x <> auth.uid())
    then raise exception 'may only save/unsave for yourself'; end if;
  end if;
  if new.cleared_by is distinct from old.cleared_by then
    if (select coalesce(array_agg(x order by x), '{}') from unnest(new.cleared_by) x where x <> auth.uid())
       is distinct from
       (select coalesce(array_agg(x order by x), '{}') from unnest(old.cleared_by) x where x <> auth.uid())
    then raise exception 'may only clear for yourself'; end if;
  end if;
  return new;
end $$;


-- Source: chat_views.sql
-- ============================================================================
-- Chat messages are viewable 3 times (Snapchat allows 1). Each time the viewer
-- leaves the conversation counts as one view; after the 3rd, the message clears
-- for them. Per-user via a jsonb leave counter, so it never vanishes for the
-- other party early. Saved messages are exempt.
-- ============================================================================

alter table public.messages add column if not exists view_leaves jsonb not null default '{}';

create or replace function public.clear_viewed_chats(other uuid)
returns void language sql security definer set search_path = public as $$
  -- Both SET clauses read the OLD row: increment this viewer's leave count, and
  -- clear only once that count reaches 3.
  update public.messages
     set view_leaves = jsonb_set(
           view_leaves,
           array[auth.uid()::text],
           to_jsonb(coalesce((view_leaves ->> auth.uid()::text)::int, 0) + 1)
         ),
         cleared_by = case
           when coalesce((view_leaves ->> auth.uid()::text)::int, 0) + 1 >= 3
                and not (auth.uid() = any(cleared_by))
             then array_append(cleared_by, auth.uid())
           else cleared_by end
   where array[user_a, user_b] = public.pair_key(auth.uid(), other)
     and opened_at is not null
     and saved_by = '{}'
     and (kind = 'chat' or sender_id = auth.uid())
     and not (auth.uid() = any(cleared_by));
$$;
revoke all on function public.clear_viewed_chats(uuid) from public;
grant execute on function public.clear_viewed_chats(uuid) to authenticated;

select 'chat 3-view enabled' as status;


-- Source: composer.sql
-- ============================================================================
-- Allow voice-note and sticker messages in chat.
--   kind 'voice'   -> media_path is an audio clip (media_type 'audio')
--   kind 'sticker' -> body holds a single emoji, rendered large
-- Both are ephemeral like chats (isVisibleTo treats non-snap as chat rules).
-- ============================================================================

alter table public.messages drop constraint if exists messages_kind_check;
alter table public.messages add constraint messages_kind_check
  check (kind in ('chat', 'snap', 'voice', 'sticker'));

alter table public.messages drop constraint if exists messages_media_type_check;
alter table public.messages add constraint messages_media_type_check
  check (media_type is null or media_type in ('image', 'video', 'audio'));

-- A voice note must carry media, just like a snap.
alter table public.messages drop constraint if exists snap_has_media;
alter table public.messages add constraint snap_has_media
  check (kind not in ('snap', 'voice') or media_path is not null);

select 'composer kinds enabled' as status;


-- Source: features.sql
-- ============================================================================
-- avatar_emoji (make the ad-hoc column reproducible) + message reactions.
-- ============================================================================

-- avatar_emoji: column, grant, and expose it in the username lookup so friends
-- see each other's chosen emoji.
alter table public.profiles add column if not exists avatar_emoji text;
grant update (avatar_emoji) on public.profiles to authenticated;

-- Return-type changed (added avatar_emoji), so the old signature must be dropped.
drop function if exists public.lookup_username(citext);
create or replace function public.lookup_username(u citext)
returns table (id uuid, username citext, display_name text, avatar_seed text, avatar_hue int, avatar_emoji text)
language sql stable security definer set search_path = public as $$
  select p.id, p.username, p.display_name, p.avatar_seed, p.avatar_hue, p.avatar_emoji
    from public.profiles p where p.username = u;
$$;
revoke all on function public.lookup_username(citext) from public;
grant execute on function public.lookup_username(citext) to authenticated;

-- ----------------------------------------------------------------------------
-- Reactions: a jsonb map of user_id -> emoji on each message (Apple-style
-- tapback; one reaction per user). Written ONLY via the RPC (which is
-- SECURITY DEFINER and touches just the caller's own key), so no direct
-- table-update grant is given — that prevents overwriting others' reactions.
-- ----------------------------------------------------------------------------
alter table public.messages add column if not exists reactions jsonb not null default '{}';

create or replace function public.react_to_message(msg uuid, emoji text)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set reactions = case
           when emoji is null or emoji = ''
             then reactions - auth.uid()::text
           else jsonb_set(reactions, array[auth.uid()::text], to_jsonb(emoji), true)
         end
   where id = msg and auth.uid() in (user_a, user_b);
$$;
revoke all on function public.react_to_message(uuid, text) from public;
grant execute on function public.react_to_message(uuid, text) to authenticated;

-- ----------------------------------------------------------------------------
-- Profile changes (emoji / name) should reach friends live, so publish the
-- profiles table for realtime.
-- ----------------------------------------------------------------------------
do $$
begin
  alter publication supabase_realtime add table public.profiles;
exception when duplicate_object then null;
end $$;

-- ----------------------------------------------------------------------------
-- Atomic save/unsave (B3): avoids the client read-modify-write race that could
-- silently drop the other party's entry and trip the guard.
-- ----------------------------------------------------------------------------
create or replace function public.toggle_saved(msg uuid)
returns uuid[] language plpgsql security definer set search_path = public as $$
declare result uuid[];
begin
  update public.messages
     set saved_by = case when auth.uid() = any(saved_by)
                         then array_remove(saved_by, auth.uid())
                         else array_append(saved_by, auth.uid()) end
   where id = msg and auth.uid() in (user_a, user_b)
   returning saved_by into result;
  return coalesce(result, '{}');
end $$;
revoke all on function public.toggle_saved(uuid) from public;
grant execute on function public.toggle_saved(uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- Also purge fully-cleared messages so "delete after viewing" actually removes
-- them server-side (both parties cleared, none saved).
-- ----------------------------------------------------------------------------
create or replace function public.purge_expired()
returns void language plpgsql security definer set search_path = public as $$
begin
  with gone as (
    delete from public.messages
     where saved_by = '{}'
       and ((opened_at is not null and opened_at < now() - interval '24 hours')
            or (opened_at is null and created_at < now() - interval '31 days')
            or (unsent_at is not null and unsent_at < now() - interval '1 hour')
            or (cardinality(cleared_by) >= 2))
    returning media_path)
  delete from storage.objects
   where bucket_id = 'media' and name in (select media_path from gone where media_path is not null);

  with dead as (delete from public.stories where expires_at < now() returning media_path)
  delete from storage.objects
   where bucket_id = 'media' and name in (select media_path from dead where media_path is not null);
end $$;


-- Source: mark_read.sql
-- ============================================================================
-- Atomic "mark incoming chats read" when a conversation is opened — one
-- statement, one realtime event, so the chat-list clears the New indicator
-- reliably (no per-message race).
-- ============================================================================
create or replace function public.mark_chats_opened(other uuid)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set opened_at = now()
   where array[user_a, user_b] = public.pair_key(auth.uid(), other)
     and kind = 'chat'
     and sender_id <> auth.uid()
     and opened_at is null;
$$;
revoke all on function public.mark_chats_opened(uuid) from public;
grant execute on function public.mark_chats_opened(uuid) to authenticated;


-- Source: repair.sql
-- ============================================================================
-- Repair: re-create RPCs that aren't resolving (react_to_message, toggle_saved,
-- record_snap_open), ensure real users are mutually accepted friends, and force
-- a PostgREST schema-cache reload. Idempotent.
-- ============================================================================

-- Schema repair must preserve relationship consent and blocked state.

-- 1b. Ensure the columns the RPCs depend on exist FIRST (snap_reopen.sql may
--     have truncated on paste, so open_count/reactions/cleared_by can be absent).
alter table public.messages add column if not exists open_count int not null default 0;
alter table public.messages add column if not exists reactions jsonb not null default '{}';
alter table public.messages add column if not exists cleared_by uuid[] not null default '{}';
alter table public.messages add column if not exists pending_clear_by uuid[] not null default '{}';
grant update (open_count) on public.messages to authenticated;

-- 2. Re-create the RPCs (idempotent).
create or replace function public.record_snap_open(msg uuid)
returns int language sql security definer set search_path = public as $$
  update public.messages
     set open_count = open_count + 1, opened_at = coalesce(opened_at, now())
   where id = msg and auth.uid() in (user_a, user_b) and sender_id <> auth.uid()
   returning open_count;
$$;
revoke all on function public.record_snap_open(uuid) from public;
grant execute on function public.record_snap_open(uuid) to authenticated;

create or replace function public.react_to_message(msg uuid, emoji text)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set reactions = case when emoji is null or emoji = ''
                          then reactions - auth.uid()::text
                          else jsonb_set(reactions, array[auth.uid()::text], to_jsonb(emoji), true) end
   where id = msg and auth.uid() in (user_a, user_b);
$$;
revoke all on function public.react_to_message(uuid, text) from public;
grant execute on function public.react_to_message(uuid, text) to authenticated;

create or replace function public.toggle_saved(msg uuid)
returns uuid[] language plpgsql security definer set search_path = public as $$
declare result uuid[];
begin
  update public.messages
     set saved_by = case when auth.uid() = any(saved_by)
                         then array_remove(saved_by, auth.uid())
                         else array_append(saved_by, auth.uid()) end
   where id = msg and auth.uid() in (user_a, user_b)
   returning saved_by into result;
  return coalesce(result, '{}');
end $$;
revoke all on function public.toggle_saved(uuid) from public;
grant execute on function public.toggle_saved(uuid) to authenticated;

-- 3. Re-apply the full update guard (covers every mutable column).
create or replace function public.guard_message_update()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if old.opened_at     is not null and new.opened_at     is distinct from old.opened_at     then raise exception 'opened_at is immutable'; end if;
  if old.screenshot_at is not null and new.screenshot_at is distinct from old.screenshot_at then raise exception 'screenshot_at is immutable'; end if;
  if old.replayed_at   is not null and new.replayed_at   is distinct from old.replayed_at   then raise exception 'replayed_at is immutable'; end if;
  if old.unsent_at is not null and new.unsent_at is distinct from old.unsent_at then raise exception 'message already unsent'; end if;
  if new.unsent_at is not null and old.unsent_at is null and old.sender_id <> auth.uid() then raise exception 'only the sender may unsend'; end if;
  if new.open_count <> old.open_count then
    if new.open_count < old.open_count then raise exception 'open_count cannot decrease'; end if;
    if auth.uid() = old.sender_id then raise exception 'sender cannot open own snap'; end if;
  end if;
  if new.saved_by is distinct from old.saved_by then
    if (select coalesce(array_agg(x order by x),'{}') from unnest(new.saved_by) x where x <> auth.uid())
       is distinct from (select coalesce(array_agg(x order by x),'{}') from unnest(old.saved_by) x where x <> auth.uid())
    then raise exception 'may only save/unsave for yourself'; end if;
  end if;
  if new.cleared_by is distinct from old.cleared_by then
    if (select coalesce(array_agg(x order by x),'{}') from unnest(new.cleared_by) x where x <> auth.uid())
       is distinct from (select coalesce(array_agg(x order by x),'{}') from unnest(old.cleared_by) x where x <> auth.uid())
    then raise exception 'may only clear for yourself'; end if;
  end if;
  return new;
end $$;
drop trigger if exists on_message_update on public.messages;
create trigger on_message_update before update on public.messages
  for each row execute function public.guard_message_update();

-- 4. Force PostgREST to reload its schema cache so the new functions resolve.
notify pgrst, 'reload schema';

select 'repaired' as status;


-- Source: stories_fix.sql
-- ============================================================================
-- Stories were never persisting. hardening.sql revoked table-wide privileges
-- and re-granted per table, but public.stories got SELECT + DELETE for the
-- authenticated role and never INSERT. So every "post story" failed with 42501
-- (permission denied) *before* the RLS write policy was even evaluated, and the
-- table stayed empty — the reason a user's own posted stories never showed.
--
-- Fix: grant INSERT, and extend the lifetime from 24h to 48h (2 days) as
-- requested. RLS (stories_write: with check user_id = auth.uid()) still gates
-- WHICH rows may be inserted; this grant just lets the role insert at all.
-- ============================================================================

grant insert on public.stories to authenticated;

alter table public.stories
  alter column expires_at set default now() + interval '48 hours';

-- Any stories already posted keep the full 2 days (none today, but harmless).
update public.stories
   set expires_at = created_at + interval '48 hours'
 where expires_at < created_at + interval '48 hours';

notify pgrst, 'reload schema';

select 'stories: INSERT granted + 48h (2-day) expiry' as status;


-- Source: ephemeral_media.sql
-- ============================================================================
-- Make voice notes and stickers ephemeral like chats. Previously
-- mark_chats_opened and clear_viewed_chats were kind='chat' only, so a RECEIVED
-- voice/sticker never got opened_at set and never entered the 3-view clear —
-- it lingered ~31 days AND showed a permanent "New" badge (the chat-list
-- indicator keys off the last message's opened_at for any kind).
--
-- After this: opening a conversation marks received voice/stickers seen (clears
-- New), and they clear across 3 visits via the same view_leaves counter as
-- chats. isVisibleTo already handles all non-snap kinds identically, so no
-- separate visibility rule is needed.
-- ============================================================================

create or replace function public.mark_chats_opened(other uuid)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set opened_at = now()
   where array[user_a, user_b] = public.pair_key(auth.uid(), other)
     and kind in ('chat', 'voice', 'sticker')
     and sender_id <> auth.uid()
     and opened_at is null;
$$;
revoke all on function public.mark_chats_opened(uuid) from public;
grant execute on function public.mark_chats_opened(uuid) to authenticated;

create or replace function public.clear_viewed_chats(other uuid)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set view_leaves = jsonb_set(
           view_leaves,
           array[auth.uid()::text],
           to_jsonb(coalesce((view_leaves ->> auth.uid()::text)::int, 0) + 1)
         ),
         cleared_by = case
           when coalesce((view_leaves ->> auth.uid()::text)::int, 0) + 1 >= 3
                and not (auth.uid() = any(cleared_by))
             then array_append(cleared_by, auth.uid())
           else cleared_by end
   where array[user_a, user_b] = public.pair_key(auth.uid(), other)
     and opened_at is not null
     and saved_by = '{}'
     and (kind in ('chat', 'voice', 'sticker') or sender_id = auth.uid())
     and not (auth.uid() = any(cleared_by));
$$;
revoke all on function public.clear_viewed_chats(uuid) from public;
grant execute on function public.clear_viewed_chats(uuid) to authenticated;

select 'voice + stickers now ephemeral (3-view, like chats)' as status;


-- Source: chat_backup.sql
-- ============================================================================
-- Backend-only 3-day chat backup (safety net). Every message is snapshotted at
-- insert time into private.message_backup and kept for 3 days, independent of
-- the app's ephemerality (UI clears / message purges never touch the backup).
--
-- This is invisible to the app: the table lives in the `private` schema, which
-- PostgREST does not expose, and the app roles have no access. Only the backend
-- (service_role / postgres via the SQL editor) can read it. No client, UI, or
-- app change is involved — a trigger does the copying passively.
-- ============================================================================

create schema if not exists private;
revoke all on schema private from anon, authenticated;

create table if not exists private.message_backup (
  backup_id      bigint generated always as identity primary key,
  message_id     uuid not null,
  user_a         uuid,
  user_b         uuid,
  sender_id      uuid,
  kind           text,
  body           text,
  media_path     text,
  media_type     text,
  view_seconds   int,
  has_audio      boolean,
  msg_created_at timestamptz,
  archived_at    timestamptz not null default now()
);
create index if not exists message_backup_archived_idx on private.message_backup (archived_at);
create index if not exists message_backup_pair_idx on private.message_backup (user_a, user_b);

-- Snapshot every new message. SECURITY DEFINER so it runs regardless of the
-- inserting user's (deliberately narrow) grants; it only ever writes the backup.
create or replace function private.backup_message()
returns trigger language plpgsql security definer set search_path = private, public as $$
begin
  -- The backup is a best-effort safety net. It runs inside the user's INSERT
  -- transaction, so wrap it: a backup failure must NEVER roll back a real
  -- message send (the hottest path in the app).
  begin
    insert into private.message_backup
      (message_id, user_a, user_b, sender_id, kind, body, media_path,
       media_type, view_seconds, has_audio, msg_created_at)
    values
      (new.id, new.user_a, new.user_b, new.sender_id, new.kind, new.body, new.media_path,
       new.media_type, new.view_seconds, new.has_audio, new.created_at);
  exception when others then
    null; -- swallow: never block the send on a backup problem
  end;
  return new;
end $$;

drop trigger if exists trg_backup_message on public.messages;
create trigger trg_backup_message
  after insert on public.messages
  for each row execute function private.backup_message();

-- Retention: keep 3 days, then drop.
create or replace function private.purge_message_backup()
returns void language sql security definer set search_path = private as $$
  delete from private.message_backup where archived_at < now() - interval '3 days';
$$;

-- Schedule the purge hourly via pg_cron; don't fail the migration if cron is
-- unavailable — the table + trigger are the essential parts.
do $$
begin
  perform cron.unschedule('purge-message-backup');
exception when others then null;
end $$;
do $$
begin
  perform cron.schedule('purge-message-backup', '23 * * * *', 'select private.purge_message_backup()');
exception when others then raise notice 'cron scheduling skipped: %', sqlerrm;
end $$;

select 'private.message_backup enabled — 3-day backend-only chat backup' as status;


-- Source: memories.sql
-- ============================================================================
-- Memories: a private gallery of your own saved snaps. Owner-only — nobody
-- else can read another person's Memories. Media lives in the existing `media`
-- bucket under <uid>/memories/, so the media_upload (own-uid prefix) and
-- media_read (owner) storage policies already cover it.
-- ============================================================================

create table if not exists public.memories (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles(id) on delete cascade,
  media_path  text not null,
  media_type  text not null default 'image' check (media_type in ('image','video')),
  caption     text,
  created_at  timestamptz not null default now()
);
create index if not exists memories_user_idx on public.memories (user_id, created_at desc);

alter table public.memories enable row level security;

drop policy if exists memories_own on public.memories;
create policy memories_own on public.memories
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- Owner-only: read/add/remove your own. No UPDATE (memories are immutable).
grant select, insert, delete on public.memories to authenticated;

notify pgrst, 'reload schema';
select 'memories table created (private owner-only gallery)' as status;


-- Source: bots.sql
-- ============================================================================
-- Motivation bots.
-- Keep vivek + sneha (real) and 5 bot accounts. Each morning every real user
-- receives a motivational quote from a bot friend. Fully automated (pg_cron),
-- and defensive so one bad row never stops the batch.
-- ============================================================================

-- Account deletion belongs in explicit administrative operations, never migrations.

-- 2. Mark the 5 bots.
alter table public.profiles add column if not exists is_bot boolean not null default false;
update public.profiles set is_bot = true
 where username in ('aarav','isha','priya','karan','nisha');
update public.profiles set is_bot = false
 where username in ('vivek','sneha');

-- 3. Every real user must be an accepted friend of every bot (so the quote lands
--    in their chat list). Backfill existing pairs...
insert into public.friendships (user_a, user_b, requested_by, status)
select least(r.id, b.id), greatest(r.id, b.id), b.id, 'accepted'
  from public.profiles r
  join public.profiles b on b.is_bot and not r.is_bot
 on conflict (user_a, user_b) do nothing;

-- ...and auto-friend any FUTURE real user with all bots on signup.
create or replace function public.autofriend_bots()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.is_bot then return new; end if;
  insert into public.friendships (user_a, user_b, requested_by, status)
  select least(new.id, b.id), greatest(new.id, b.id), b.id, 'accepted'
    from public.profiles b where b.is_bot
  on conflict (user_a, user_b) do nothing;
  return new;
exception when others then
  return new; -- never block a signup on this
end $$;

drop trigger if exists on_profile_autofriend on public.profiles;
create trigger on_profile_autofriend after insert on public.profiles
  for each row execute function public.autofriend_bots();

-- 4. Quotes.
create table if not exists public.bot_quotes (id serial primary key, text text not null);
insert into public.bot_quotes (text)
select v.text from (values
  ('Good morning! Today is a fresh start — make it count. 🌅'),
  ('Small steps every day add up to big results. Keep going. 💪'),
  ('You are capable of amazing things. Believe it this morning. ✨'),
  ('Energy flows where attention goes. Focus on what matters today. ⚡'),
  ('Discipline is choosing what you want most over what you want now. 🔥'),
  ('Rise and shine — the world needs your energy today. ☀️'),
  ('Every morning is a chance to be better than yesterday. 🚀'),
  ('Your only limit is the one you set in your mind. Break it. 🧠'),
  ('Great things never come from comfort zones. Step out today. 🌱'),
  ('Start where you are. Use what you have. Do what you can. 🙌'),
  ('The secret of getting ahead is getting started. Begin now. 🏁'),
  ('Wake up with determination, go to bed with satisfaction. 🌟'),
  ('Push yourself, because no one else is going to do it for you. 💥'),
  ('A little progress each day adds up to big results. 📈'),
  ('Dream big, start small, act now. Your morning is calling. 🎯'),
  ('You did not wake up today to be mediocre. Give it your all. 🦁'),
  ('Fuel your day with positivity and watch what unfolds. 🌈'),
  ('Hard work beats talent when talent does not work hard. 🛠️'),
  ('Be the energy you want to attract today. 🔋'),
  ('One day or day one — you decide. Make it day one. 💫')
) v(text)
where not exists (select 1 from public.bot_quotes);

-- 5. The morning send. SECURITY DEFINER so it runs as owner (bypasses RLS) and
--    each recipient is wrapped so a single failure can't halt the batch.
create or replace function public.send_morning_quotes()
returns int language plpgsql security definer set search_path = public as $$
declare
  ru record; bot_id uuid; q text; sent int := 0;
begin
  for ru in select id from public.profiles where not is_bot loop
    begin
      -- a bot friend, rotating per user per day
      select b.id into bot_id from public.profiles b
       where b.is_bot
       order by md5(b.id::text || ru.id::text || current_date::text)
       limit 1;
      -- a quote, rotating per user per day
      select text into q from public.bot_quotes
       order by md5(id::text || ru.id::text || current_date::text)
       limit 1;
      if bot_id is null or q is null then continue; end if;
      insert into public.messages (user_a, user_b, sender_id, kind, body, delivered_at)
      values (least(bot_id, ru.id), greatest(bot_id, ru.id), bot_id, 'chat', q, now());
      sent := sent + 1;
    exception when others then
      -- swallow and continue with the next user
      null;
    end;
  end loop;
  return sent;
end $$;

-- 6. Send one round now so it's verifiable immediately. (Daily scheduling via
--    pg_cron is applied separately — see supabase/cron.sql — because enabling
--    the extension can abort a batched transaction on some projects.)
-- Scheduled delivery only; migration replay must not send messages.


