-- Source: snap_map.sql
-- ============================================================================
-- Snap Map: opt-in live location. Ghost Mode is the DEFAULT — a row is only
-- visible to friends when sharing = true, and users start not sharing. An
-- accepted friend can read your location only while you're sharing; you can
-- always read/write your own.
-- ============================================================================
create table if not exists public.locations (
  user_id    uuid primary key references public.profiles(id) on delete cascade,
  lat        double precision not null,
  lng        double precision not null,
  sharing    boolean not null default false, -- Ghost Mode is the default
  updated_at timestamptz not null default now()
);

alter table public.locations enable row level security;

drop policy if exists locations_read on public.locations;
create policy locations_read on public.locations
  for select to authenticated using (
    user_id = auth.uid()
    or (
      sharing
      and exists (
        select 1 from public.friendships f
         where f.status = 'accepted'
           and array[f.user_a, f.user_b] = public.pair_key(auth.uid(), locations.user_id)
      )
    )
  );

drop policy if exists locations_write on public.locations;
create policy locations_write on public.locations
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

grant select, insert, update, delete on public.locations to authenticated;

notify pgrst, 'reload schema';
select 'snap map: locations table (Ghost Mode default) enabled' as status;


-- Source: security_qa.sql
-- ============================================================================
-- Security-question password recovery (no email needed). The answer is
-- bcrypt-hashed; the reset RPC verifies it and updates the login password
-- directly in auth.users (GoTrue and pgcrypto both use bcrypt, so the new
-- password works on the next login). SECURITY DEFINER so the reset works
-- pre-auth. The answer hash is never readable by the client.
-- ============================================================================
create extension if not exists pgcrypto with schema extensions;

create table if not exists public.security_questions (
  user_id     uuid primary key references public.profiles(id) on delete cascade,
  question    text not null,
  answer_hash text not null,
  updated_at  timestamptz not null default now()
);
alter table public.security_questions enable row level security;

-- Users may write their own row; NOBODY can read answer hashes from the client.
drop policy if exists secq_write on public.security_questions;
create policy secq_write on public.security_questions
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());
revoke select on public.security_questions from authenticated, anon;
grant insert, update, delete on public.security_questions to authenticated;

-- Set/replace your own Q+A (answer hashed server-side).
create or replace function public.set_security_question(question text, answer text)
returns void language plpgsql security definer set search_path = public, extensions as $$
begin
  insert into public.security_questions (user_id, question, answer_hash, updated_at)
  values (auth.uid(), question, extensions.crypt(lower(trim(answer)), extensions.gen_salt('bf')), now())
  on conflict (user_id) do update
    set question = excluded.question, answer_hash = excluded.answer_hash, updated_at = now();
end $$;
revoke all on function public.set_security_question(text, text) from public;
grant execute on function public.set_security_question(text, text) to authenticated;

-- The security question for a username (to show on the reset screen). Pre-auth.
create or replace function public.get_security_question(uname text)
returns text language sql security definer set search_path = public as $$
  select sq.question
    from public.profiles p
    join public.security_questions sq on sq.user_id = p.id
   where p.username = lower(trim(uname));
$$;
revoke all on function public.get_security_question(text) from public;
grant execute on function public.get_security_question(text) to anon, authenticated;

-- Verify the answer and set a new login password. Returns true on success.
create or replace function public.reset_password(uname text, answer text, new_password text)
returns boolean language plpgsql security definer set search_path = public, extensions, auth as $$
declare uid uuid; stored text;
begin
  if length(new_password) < 6 then return false; end if;
  select p.id, sq.answer_hash into uid, stored
    from public.profiles p
    join public.security_questions sq on sq.user_id = p.id
   where p.username = lower(trim(uname));
  if uid is null or stored is null then return false; end if;
  if extensions.crypt(lower(trim(answer)), stored) <> stored then return false; end if;
  update auth.users
     set encrypted_password = extensions.crypt(new_password, extensions.gen_salt('bf')),
         updated_at = now()
   where id = uid;
  return true;
end $$;
revoke all on function public.reset_password(text, text, text) from public;
grant execute on function public.reset_password(text, text, text) to anon, authenticated;

notify pgrst, 'reload schema';
select 'security-question password recovery enabled' as status;


-- Source: call_fix.sql
-- ============================================================================
-- Call-log fixes (audit findings 2 & 4).
--
-- 2. `logCall` stores the call DURATION in messages.view_seconds, but the
--    `view_seconds_sane` constraint only allowed 1..60. A MISSED call (0s) or a
--    call longer than 60s violated the check → 23514, which useCall swallows
--    with .catch(() => {}), so the call log silently never wrote. That is
--    exactly the "call was made / they were unavailable" log the app is meant
--    to show. Exempt kind='call' from the range.
--
-- 4. `mark_chats_opened` didn't include 'call', so a received call log as the
--    last message left a permanent "unread" indicator in the chat list.
-- ============================================================================

-- 2 ------------------------------------------------------------------------
alter table public.messages drop constraint if exists view_seconds_sane;
alter table public.messages add constraint view_seconds_sane
  check (kind = 'call' or view_seconds is null or view_seconds between 1 and 60);

-- 4 ------------------------------------------------------------------------
create or replace function public.mark_chats_opened(other uuid)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set opened_at = coalesce(opened_at, now())
   where auth.uid() in (user_a, user_b)
     and sender_id = other
     and kind in ('chat', 'voice', 'sticker', 'call')
     and opened_at is null;
$$;
revoke all on function public.mark_chats_opened(uuid) from public;
grant execute on function public.mark_chats_opened(uuid) to authenticated;

notify pgrst, 'reload schema';
select 'call-log constraint + mark-opened fixed' as status;


-- Source: security_qa_hardening.sql
-- ============================================================================
-- Hardening for security-question recovery (audit findings 2 & 3).
--
-- 2. TAKEOVER FIX: an empty / whitespace-only answer hashed the empty string,
--    and the anon-callable reset_password would then match a blank guess →
--    unauthenticated account takeover. Reject empty answers in BOTH RPCs (the
--    client guards too, but the RPCs are directly callable with the anon key,
--    so the authoritative check must be server-side).
--
-- 3. Rate-limit answer guessing (lock the account's reset after 5 wrong tries
--    for 15 min) and raise the bcrypt cost so grinding a low-entropy answer is
--    slow. attempts/locked_until live on the row the client cannot SELECT.
-- ============================================================================
alter table public.security_questions
  add column if not exists attempts     int         not null default 0,
  add column if not exists locked_until  timestamptz;

-- Set/replace your own Q+A: reject empty answer, cost-10 hash, clear any lock.
create or replace function public.set_security_question(question text, answer text)
returns void language plpgsql security definer set search_path = public, extensions as $$
begin
  if length(trim(coalesce(answer, ''))) = 0 then
    raise exception 'answer must not be empty';
  end if;
  insert into public.security_questions (user_id, question, answer_hash, attempts, locked_until, updated_at)
  values (auth.uid(), question,
          extensions.crypt(lower(trim(answer)), extensions.gen_salt('bf', 10)), 0, null, now())
  on conflict (user_id) do update
    set question = excluded.question, answer_hash = excluded.answer_hash,
        attempts = 0, locked_until = null, updated_at = now();
end $$;
revoke all on function public.set_security_question(text, text) from public;
grant execute on function public.set_security_question(text, text) to authenticated;

-- Verify the answer (rate-limited) and set a new login password.
create or replace function public.reset_password(uname text, answer text, new_password text)
returns boolean language plpgsql security definer set search_path = public, extensions, auth as $$
declare uid uuid; stored text; locked timestamptz; tries int;
begin
  if length(trim(coalesce(answer, ''))) = 0 then return false; end if;  -- (2) no blank answers
  if length(new_password) < 6 then return false; end if;
  select p.id, sq.answer_hash, sq.locked_until, sq.attempts
    into uid, stored, locked, tries
    from public.profiles p
    join public.security_questions sq on sq.user_id = p.id
   where p.username = lower(trim(uname));
  if uid is null or stored is null then return false; end if;
  if locked is not null and locked > now() then return false; end if;  -- (3) locked out
  if extensions.crypt(lower(trim(answer)), stored) <> stored then
    -- wrong answer: count it; lock the reset after 5 tries for 15 minutes
    update public.security_questions
       set attempts = attempts + 1,
           locked_until = case when attempts + 1 >= 5 then now() + interval '15 minutes'
                               else locked_until end
     where user_id = uid;
    return false;
  end if;
  -- correct: change the password (cost-10, matching GoTrue) and clear the counter
  update auth.users
     set encrypted_password = extensions.crypt(new_password, extensions.gen_salt('bf', 10)),
         updated_at = now()
   where id = uid;
  update public.security_questions set attempts = 0, locked_until = null where user_id = uid;
  return true;
end $$;
revoke all on function public.reset_password(text, text, text) from public;
grant execute on function public.reset_password(text, text, text) to anon, authenticated;

notify pgrst, 'reload schema';
select 'security-question hardening applied' as status;


-- Source: core_fixes.sql
-- ============================================================================
-- Core-algorithm fixes (deep-audit findings).
--
-- 1. clear_viewed_chats swept the caller's OWN messages via `sender_id =
--    auth.uid()`. That clause was meant to also clear the sender's own SNAP
--    status rows — but it caught `kind='call'` logs too. Combined with
--    call_fix.sql now stamping opened_at on call logs, a caller's call log got
--    swept into the 3-visit counter and DISAPPEARED for the caller after 3
--    visits (while persisting for the recipient — asymmetric). Scope the clause
--    to snaps so call logs are never swept.
--
-- 2. bump_streak's once-per-window guard required STRICTLY >24h since the last
--    increment, anchored to the drifting last_increment timestamp. A pair
--    snapping at roughly the same time each day would be blocked (~23.5h < 24h)
--    and the streak would stall/under-count. Relax to 20h (the pre-hardening
--    value): still blocks same-day double counts (exchanges <20h apart) while
--    letting a normal daily cadence advance. The `least(a_ts,b_ts) >
--    last_increment` clause independently prevents intra-window double counting.
--
-- 3. getSnapScore(friend) was computed under the CALLER's RLS view, so a
--    friend's score was really the caller's own activity (inflated, identical
--    for every friend). Add a SECURITY DEFINER RPC that counts the TARGET's
--    snaps across their own conversations.
-- ============================================================================

-- 1 ------------------------------------------------------------------------
create or replace function public.clear_viewed_chats(other uuid)
returns void language sql security definer set search_path = public as $$
  update public.messages
     set view_leaves = jsonb_set(
           view_leaves,
           array[auth.uid()::text],
           to_jsonb(coalesce((view_leaves ->> auth.uid()::text)::int, 0) + 1)
         ),
         cleared_by = case
           when coalesce((view_leaves ->> auth.uid()::text)::int, 0) + 1 >= 3
                and not (auth.uid() = any(cleared_by))
             then array_append(cleared_by, auth.uid())
           else cleared_by end
   where array[user_a, user_b] = public.pair_key(auth.uid(), other)
     and opened_at is not null
     and saved_by = '{}'
     and (kind in ('chat', 'voice', 'sticker') or (sender_id = auth.uid() and kind = 'snap'))
     and not (auth.uid() = any(cleared_by));
$$;
revoke all on function public.clear_viewed_chats(uuid) from public;
grant execute on function public.clear_viewed_chats(uuid) to authenticated;

-- 2 ------------------------------------------------------------------------
create or replace function public.bump_streak()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  s public.streaks%rowtype;
  now_ts timestamptz := now();
  sender_is_a boolean := (new.sender_id = new.user_a);
  a_ts timestamptz;
  b_ts timestamptz;
begin
  if new.kind <> 'snap' then return new; end if;

  insert into public.streaks (user_a, user_b) values (new.user_a, new.user_b)
    on conflict (user_a, user_b) do nothing;
  select * into s from public.streaks
   where user_a = new.user_a and user_b = new.user_b for update;
  if not found then return new; end if;

  if s.count > 0 and (
       s.last_snap_a is null or s.last_snap_b is null
       or s.last_snap_a < now_ts - interval '24 hours'
       or s.last_snap_b < now_ts - interval '24 hours') then
    s.count := 0; s.last_increment := null;
  end if;

  a_ts := case when sender_is_a then now_ts else s.last_snap_a end;
  b_ts := case when sender_is_a then s.last_snap_b else now_ts end;

  if a_ts is not null and b_ts is not null
     and a_ts > now_ts - interval '24 hours'
     and b_ts > now_ts - interval '24 hours'
     and (s.last_increment is null
          or (least(a_ts, b_ts) > s.last_increment
              and s.last_increment < now_ts - interval '20 hours'))
  then
    s.count := greatest(s.count, 0) + 1;
    s.last_increment := now_ts;
  end if;

  update public.streaks
     set count = s.count, last_snap_a = a_ts, last_snap_b = b_ts,
         last_increment = s.last_increment
   where user_a = new.user_a and user_b = new.user_b;
  return new;
end $$;

-- 3 ------------------------------------------------------------------------
-- Count the target user's snaps across their own conversations (definer, so it
-- isn't bounded by the caller's RLS view). Every snap in a conversation the
-- target is in is one they sent or received, so pair-membership = sent + recv.
create or replace function public.get_snap_score(target uuid)
returns int language sql security definer set search_path = public as $$
  select count(*)::int from public.messages
   where kind = 'snap' and (user_a = target or user_b = target);
$$;
revoke all on function public.get_snap_score(uuid) from public;
grant execute on function public.get_snap_score(uuid) to authenticated;

notify pgrst, 'reload schema';
select 'core fixes applied (call-log clear, streak cadence, snap score)' as status;


-- Source: streak_fix.sql
-- ============================================================================
-- Friendlier streaks (deep-audit + real-usage finding).
--
-- The Snapchat rule (both must send a PHOTO SNAP within each 24h window) left
-- real pairs stuck at 1: one person snaps often, the other mostly texts, so the
-- mutual-snap window keeps breaking. For this app the streak should reflect that
-- two people are TALKING every day, so count any real message (chat / snap /
-- voice / sticker — not call logs). Guards kept: a one-sided burst never
-- advances it (BOTH sides must have sent since the last count), and it advances
-- at most once per ~20h (once a day). Window widened 24h -> 36h so a late day
-- doesn't kill the streak; it only breaks after a genuine ~1.5-day silence.
-- ============================================================================
create or replace function public.bump_streak()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  s public.streaks%rowtype;
  now_ts timestamptz := now();
  sender_is_a boolean := (new.sender_id = new.user_a);
  a_ts timestamptz;
  b_ts timestamptz;
begin
  if new.kind = 'call' then return new; end if; -- call logs don't count

  insert into public.streaks (user_a, user_b) values (new.user_a, new.user_b)
    on conflict (user_a, user_b) do nothing;
  select * into s from public.streaks
   where user_a = new.user_a and user_b = new.user_b for update;
  if not found then return new; end if;

  -- Break only after a real gap: either side silent for >36h.
  if s.count > 0 and (
       s.last_snap_a is null or s.last_snap_b is null
       or s.last_snap_a < now_ts - interval '36 hours'
       or s.last_snap_b < now_ts - interval '36 hours') then
    s.count := 0; s.last_increment := null;
  end if;

  a_ts := case when sender_is_a then now_ts else s.last_snap_a end;
  b_ts := case when sender_is_a then s.last_snap_b else now_ts end;

  -- Advance once per ~day when BOTH have sent since the last increment.
  if a_ts is not null and b_ts is not null
     and a_ts > now_ts - interval '36 hours'
     and b_ts > now_ts - interval '36 hours'
     and (s.last_increment is null
          or (least(a_ts, b_ts) > s.last_increment
              and s.last_increment < now_ts - interval '20 hours'))
  then
    s.count := greatest(s.count, 0) + 1;
    s.last_increment := now_ts;
  end if;

  update public.streaks
     set count = s.count, last_snap_a = a_ts, last_snap_b = b_ts,
         last_increment = s.last_increment
   where user_a = new.user_a and user_b = new.user_b;
  return new;
end $$;

notify pgrst, 'reload schema';
select 'streaks now count daily two-way messaging (forgiving 36h)' as status;


