-- Source: charms.sql
-- ============================================================================
-- Friendship charms — fun computed stats for a pair, shown in the FriendSheet.
-- SECURITY DEFINER so counts aren't skewed by the caller's row visibility; only
-- ever computes for a pair the caller is IN (auth.uid() is one side). Message
-- counts reflect the CURRENT (non-purged) conversation, so they're "lately"
-- vibe stats, not lifetime — framed that way in the UI. Night/day use IST
-- (Asia/Kolkata), the users' timezone.
-- ============================================================================
create or replace function public.friendship_charms(other uuid)
returns json language sql security definer set search_path = public as $$
  with pk as (select least(auth.uid(), other) ua, greatest(auth.uid(), other) ub)
  select json_build_object(
    'streak',        coalesce((select s.count from public.streaks s, pk where s.user_a = pk.ua and s.user_b = pk.ub), 0),
    'friends_since', (select f.created_at from public.friendships f, pk where f.user_a = pk.ua and f.user_b = pk.ub),
    'anniversary',   (select a.started_on from public.anniversaries a, pk where a.user_a = pk.ua and a.user_b = pk.ub),
    'snaps',         (select count(*) from public.messages m, pk where m.kind = 'snap' and m.user_a = pk.ua and m.user_b = pk.ub),
    'my_msgs',       (select count(*) from public.messages m, pk where m.user_a = pk.ua and m.user_b = pk.ub and m.sender_id = auth.uid()),
    'their_msgs',    (select count(*) from public.messages m, pk where m.user_a = pk.ua and m.user_b = pk.ub and m.sender_id = other),
    'night_msgs',    (select count(*) from public.messages m, pk where m.user_a = pk.ua and m.user_b = pk.ub
                        and extract(hour from m.created_at at time zone 'Asia/Kolkata') in (22,23,0,1,2,3,4)),
    'morning_msgs',  (select count(*) from public.messages m, pk where m.user_a = pk.ua and m.user_b = pk.ub
                        and extract(hour from m.created_at at time zone 'Asia/Kolkata') between 5 and 10)
  );
$$;
revoke all on function public.friendship_charms(uuid) from public;
grant execute on function public.friendship_charms(uuid) to authenticated;

notify pgrst, 'reload schema';
select 'friendship_charms RPC ready' as status;


-- Source: bot_quotes_lock.sql
-- ============================================================================
-- Security-audit finding (LOW): bot_quotes was the one public table with RLS
-- OFF and default grants, so any authenticated user could INSERT/UPDATE quotes
-- that send_morning_quotes() then DMs to every real user (incl. the owner) as a
-- trusted "bot" each morning — a phishing/abuse vector. Clients never read this
-- table directly; send_morning_quotes() is SECURITY DEFINER and keeps working.
-- Lock it: enable RLS (no policy → no client access) AND revoke grants.
-- ============================================================================
alter table public.bot_quotes enable row level security;
revoke all on public.bot_quotes from anon, authenticated;

notify pgrst, 'reload schema';
select 'bot_quotes locked (RLS on, grants revoked)' as status;


-- Source: recovery_hardening_2.sql
-- ============================================================================
-- Second-round audit fixes: password-recovery session revocation, a decaying
-- guess-lockout window, and scoping the snap-score RPC to people you can
-- actually see. Supersedes the reset_password / get_snap_score definitions in
-- security_qa_hardening.sql and core_fixes.sql respectively (last applied wins).
--
-- 1. SESSION REVOCATION. reset_password changed auth.users.encrypted_password
--    but left auth.sessions / auth.refresh_tokens untouched. Recovery is the
--    flow you run precisely BECAUSE someone else may hold your account — and
--    an attacker's existing session kept refreshing indefinitely after the
--    "recovery" completed. GoTrue only checks the password at sign-in, never
--    on refresh, so changing it alone locks nobody out. Kill every session for
--    the user as part of the same transaction as the password change.
--
-- 2. LOCKOUT DoS. `attempts` never decayed: it counted wrong guesses for the
--    lifetime of the row. After 5 lifetime misses the counter stayed >= 5, so
--    every later wrong guess re-armed a fresh 15-minute lock. Since usernames
--    are enumerable (get_security_question is anon-callable by design, so the
--    reset screen can show the question), anyone could keep a stranger's
--    recovery permanently locked with one wrong guess every 15 minutes. Make
--    it a ROLLING window: misses older than the window don't count.
--
-- 3. SNAP SCORE SCOPE. get_snap_score(target) was granted to `authenticated`
--    with no relationship check, so any signed-in user could pull an activity
--    metric for an arbitrary uuid harvested from anywhere. The UI only ever
--    needs your own score and an accepted friend's. Enforce exactly that; a
--    stranger's score reads 0 rather than erroring, so the card just shows a
--    dash.
-- ============================================================================

alter table public.security_questions
  add column if not exists last_attempt_at timestamptz;

-- 1 + 2 ----------------------------------------------------------------------
create or replace function public.reset_password(uname text, answer text, new_password text)
returns boolean language plpgsql security definer set search_path = public, extensions, auth as $$
declare
  uid uuid; stored text; locked timestamptz; tries int; last_try timestamptz;
  -- Wrong guesses stop counting once this much time has passed since the last
  -- one, so the lock is a rolling window rather than a permanent state.
  window_interval constant interval := interval '15 minutes';
begin
  if length(trim(coalesce(answer, ''))) = 0 then return false; end if;
  if length(new_password) < 6 then return false; end if;

  select p.id, sq.answer_hash, sq.locked_until, sq.attempts, sq.last_attempt_at
    into uid, stored, locked, tries, last_try
    from public.profiles p
    join public.security_questions sq on sq.user_id = p.id
   where p.username = lower(trim(uname));
  if uid is null or stored is null then return false; end if;
  if locked is not null and locked > now() then return false; end if;

  -- (2) decay: a miss outside the window starts the count over.
  if last_try is null or last_try < now() - window_interval then
    tries := 0;
  end if;

  if extensions.crypt(lower(trim(answer)), stored) <> stored then
    update public.security_questions
       set attempts = tries + 1,
           last_attempt_at = now(),
           locked_until = case when tries + 1 >= 5 then now() + window_interval
                               else locked_until end
     where user_id = uid;
    return false;
  end if;

  -- Correct answer: change the password (cost-10, matching GoTrue)...
  update auth.users
     set encrypted_password = extensions.crypt(new_password, extensions.gen_salt('bf', 10)),
         updated_at = now()
   where id = uid;

  -- (1) ...and cut every existing session dead, so a session opened with the OLD
  -- password cannot outlive the reset. refresh_tokens.session_id cascades from
  -- auth.sessions; the second delete sweeps pre-session-table stragglers, whose
  -- user_id column is text in GoTrue, hence the cast. Guarded on its own so an
  -- unexpected shape there can never roll back the password change above.
  delete from auth.sessions where user_id = uid;
  begin
    delete from auth.refresh_tokens where user_id = uid::text;
  exception when others then null;
  end;

  update public.security_questions
     set attempts = 0, locked_until = null, last_attempt_at = null
   where user_id = uid;
  return true;
end $$;
revoke all on function public.reset_password(text, text, text) from public;
grant execute on function public.reset_password(text, text, text) to anon, authenticated;

-- 3 --------------------------------------------------------------------------
create or replace function public.get_snap_score(target uuid)
returns int language sql security definer set search_path = public as $$
  select case
    when target = auth.uid() or exists (
      select 1 from public.friendships f
       where f.status = 'accepted'
         and array[f.user_a, f.user_b] = public.pair_key(auth.uid(), target)
    )
    then (select count(*)::int from public.messages
           where kind = 'snap' and (user_a = target or user_b = target))
    else 0
  end;
$$;
revoke all on function public.get_snap_score(uuid) from public;
grant execute on function public.get_snap_score(uuid) to authenticated;

notify pgrst, 'reload schema';
select 'recovery: sessions revoked on reset, rolling lockout; snap score scoped' as status;


-- Source: chatlist_perf.sql
-- ============================================================================
-- Chat-list load: one query instead of N.
--
-- ChatList.load() called listMessages() once PER accepted friend — each pulling
-- a 200-row page — purely to find the newest visible message for each row. It
-- is also wired to unfiltered postgres_changes on messages / friendships /
-- streaks / profiles, so EVERY message insert anywhere in your conversations
-- re-ran the whole N x 200 sweep. On an active chat that is a full refetch per
-- message received.
--
-- latest_messages() returns just the newest few rows per conversation in a
-- single round trip. A few (not one) because visibility is decided client-side
-- by isVisibleTo — cleared / consumed / expired messages are filtered after the
-- fetch, so the row needs a little depth to fall back through before giving up
-- and showing "Tap to chat".
--
-- SECURITY INVOKER (the default): RLS on public.messages still restricts this
-- to conversations the caller is part of. The auth.uid() predicate is there to
-- narrow the scan, not to enforce access.
-- ============================================================================
create or replace function public.latest_messages(per_pair int default 4)
returns setof public.messages
language sql stable set search_path = public as $$
  select l.*
    from (
      select distinct user_a, user_b
        from public.messages
       where auth.uid() in (user_a, user_b)
    ) p
    cross join lateral (
      select m.*
        from public.messages m
       where m.user_a = p.user_a
         and m.user_b = p.user_b
         and m.unsent_at is null
       order by m.created_at desc
       limit greatest(1, least(per_pair, 20))
    ) l;
$$;
revoke all on function public.latest_messages(int) from public;
grant execute on function public.latest_messages(int) to authenticated;

-- Supports both the lateral lookup above and listMessages' newest-first paging.
create index if not exists messages_pair_recent_idx
  on public.messages (user_a, user_b, created_at desc);

notify pgrst, 'reload schema';
select 'latest_messages RPC + pair/recency index ready' as status;


-- Source: memories_thumbs.sql
-- ============================================================================
-- Memories thumbnails (egress fix).
--
-- The Memories grid rendered one tile per memory from the FULL-SIZE original —
-- so opening the screen once downloaded every original at full resolution, just
-- to fill ~120px cells, every time. `saveToMemory` now writes a small JPEG
-- alongside the original and records it here; the grid uses it and falls back
-- to media_path for rows saved before this column existed.
--
-- Nullable, so old rows stay valid. memories carries table-wide
-- (not column-scoped) grants — see memories.sql — so the new column is already
-- covered by the existing `grant select, insert, delete`, and no extra grant is
-- needed. Verify anyway: on this schema a missing grant fails with 42501 BEFORE
-- RLS is evaluated.
-- ============================================================================
alter table public.memories
  add column if not exists thumb_path text;

notify pgrst, 'reload schema';
select 'memories.thumb_path added' as status;


-- Source: push.sql
-- ============================================================================
-- Web Push subscriptions — notifications when the app is CLOSED.
--
-- Until now a call only rang if the friend already had the app open, and a
-- message produced nothing at all. A push subscription is the browser's
-- delivery address; the `push` Edge Function signs a VAPID request to it.
--
-- One row per browser/device, keyed by endpoint (the same user on phone +
-- laptop has two). `endpoint` is unique so re-subscribing the same browser
-- updates rather than duplicates.
--
-- RLS: a user manages ONLY their own subscriptions and can never read anyone
-- else's — the endpoint plus keys is enough to push to that device, so this
-- table is a capability store, not just metadata. The Edge Function reads
-- recipients' rows with the service-role key, after checking the caller is an
-- accepted friend of the recipient.
-- ============================================================================
create table if not exists public.push_subscriptions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles(id) on delete cascade,
  endpoint   text not null unique,
  p256dh     text not null,   -- client public key (base64url)
  auth       text not null,   -- client auth secret (base64url)
  user_agent text,
  created_at timestamptz not null default now()
);
create index if not exists push_subs_user_idx on public.push_subscriptions (user_id);

alter table public.push_subscriptions enable row level security;

drop policy if exists push_subs_own on public.push_subscriptions;
create policy push_subs_own on public.push_subscriptions
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

grant select, insert, update, delete on public.push_subscriptions to authenticated;

notify pgrst, 'reload schema';
select 'push_subscriptions ready' as status;


-- Source: together.sql
-- ============================================================================
-- "Together" features: birthdays, status notes, and a daily question.
--
-- All three are per-user or per-pair state with no media, so none of them touch
-- the storage policies. Day boundaries use IST (Asia/Kolkata) throughout, like
-- friendship_charms — "today's question" must roll over at the users' midnight,
-- not UTC's.
-- ============================================================================

-- The users' local day. Everything dated in this file goes through it.
create or replace function public.ist_date()
returns date language sql stable as $$
  select (now() at time zone 'Asia/Kolkata')::date;
$$;

-- ---------------------------------------------------------------------------
-- 1. Birthdays
--    status.js has referenced a 🎂 friendship emoji since the beginning with
--    no column behind it. This is that column.
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists birthday date;

-- hardening.sql revoked table-wide UPDATE on profiles and re-granted per
-- column, so a new writable column NEEDS its own grant or the write fails with
-- 42501 before RLS is even consulted. SELECT is still granted table-wide.
grant update (birthday) on public.profiles to authenticated;

-- Whose birthday is today, among the caller's accepted friends. SECURITY
-- DEFINER only to keep the date maths server-side; it never returns a profile
-- the caller couldn't already read.
create or replace function public.birthdays_today()
returns setof uuid language sql stable security definer set search_path = public as $$
  select p.id
    from public.profiles p
   where p.birthday is not null
     and to_char(p.birthday, 'MM-DD') = to_char(public.ist_date(), 'MM-DD')
     and exists (
       select 1 from public.friendships f
        where f.status = 'accepted'
          and array[f.user_a, f.user_b] = public.pair_key(auth.uid(), p.id));
$$;
revoke all on function public.birthdays_today() from public;
grant execute on function public.birthdays_today() to authenticated;

-- ---------------------------------------------------------------------------
-- 2. Status notes — a line under your name that expires after 24h.
--    One row per user (upsert), so a note replaces rather than accumulates.
-- ---------------------------------------------------------------------------
create table if not exists public.status_notes (
  user_id    uuid primary key references public.profiles(id) on delete cascade,
  body       text not null check (length(btrim(body)) between 1 and 80),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '24 hours'
);

alter table public.status_notes enable row level security;

-- Readable by you and your accepted friends, and only while unexpired — an
-- expired note is invisible immediately rather than waiting for a purge.
drop policy if exists status_read on public.status_notes;
create policy status_read on public.status_notes
  for select to authenticated using (
    expires_at > now()
    and (
      user_id = auth.uid()
      or exists (
        select 1 from public.friendships f
         where f.status = 'accepted'
           and array[f.user_a, f.user_b] = public.pair_key(auth.uid(), status_notes.user_id))
    )
  );

drop policy if exists status_write on public.status_notes;
create policy status_write on public.status_notes
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

grant select, insert, update, delete on public.status_notes to authenticated;

-- Housekeeping: expired notes are already invisible, this just stops the table
-- growing forever. Safe to call from anywhere.
create or replace function public.purge_status_notes()
returns void language sql security definer set search_path = public as $$
  delete from public.status_notes where expires_at < now() - interval '7 days';
$$;

-- ---------------------------------------------------------------------------
-- 3. Question of the day
--    One shared prompt per day. You answer; you only get to SEE their answer
--    once you've written your own. That reveal rule is the whole point — it
--    has to be enforced in RLS, not the client, or it's just a UI suggestion.
-- ---------------------------------------------------------------------------
create table if not exists public.prompts (
  id   int primary key,
  body text not null
);

-- Locked down exactly like bot_quotes (see bot_quotes_lock.sql): RLS on with no
-- policy and grants revoked, so no signed-in user can inject a "question" that
-- every pair is then shown. Clients read it only through todays_prompt().
alter table public.prompts enable row level security;
revoke all on public.prompts from anon, authenticated;

insert into public.prompts (id, body) values
  (1,  'What''s something small I did recently that you appreciated?'),
  (2,  'Where should we go the next time we get a free weekend?'),
  (3,  'What''s a song that reminds you of us?'),
  (4,  'What were you like as a kid?'),
  (5,  'What''s something you want to get better at this year?'),
  (6,  'What''s the best meal we''ve had together?'),
  (7,  'What''s something you''re worried about right now?'),
  (8,  'What''s a moment you wish you could relive?'),
  (9,  'What made you laugh today?'),
  (10, 'What''s something you''ve never told me?'),
  (11, 'What does a perfect ordinary day look like for you?'),
  (12, 'What''s the bravest thing you''ve done?'),
  (13, 'Which of my habits would you keep forever?'),
  (14, 'What are you looking forward to most this month?'),
  (15, 'What''s something you changed your mind about recently?'),
  (16, 'Where do you feel most like yourself?'),
  (17, 'What''s a compliment you got that stuck with you?'),
  (18, 'What''s the first thing you noticed about me?'),
  (19, 'What''s something you want us to do more of?'),
  (20, 'What''s the hardest thing about this week?'),
  (21, 'What''s a smell that takes you straight back somewhere?'),
  (22, 'If money didn''t matter, what would you spend your days doing?'),
  (23, 'What''s something you''re proud of that nobody noticed?'),
  (24, 'What do you need more of from me right now?'),
  (25, 'What''s a tiny thing that always cheers you up?'),
  (26, 'What''s a story from your family you love telling?'),
  (27, 'What''s something you find beautiful that most people walk past?'),
  (28, 'What would you tell yourself five years ago?'),
  (29, 'What''s the kindest thing anyone has done for you?'),
  (30, 'What are we better at now than we were a year ago?')
on conflict (id) do update set body = excluded.body;

create table if not exists public.prompt_answers (
  id         uuid primary key default gen_random_uuid(),
  user_a     uuid not null references public.profiles(id) on delete cascade,
  user_b     uuid not null references public.profiles(id) on delete cascade,
  responder  uuid not null references public.profiles(id) on delete cascade,
  on_date    date not null default public.ist_date(),
  prompt_id  int  not null references public.prompts(id),
  body       text not null check (length(btrim(body)) between 1 and 500),
  created_at timestamptz not null default now(),
  constraint prompt_answers_ordered check (user_a < user_b),
  unique (user_a, user_b, responder, on_date)
);
create index if not exists prompt_answers_pair_idx
  on public.prompt_answers (user_a, user_b, on_date);

-- Has the caller already answered for this pair/day? SECURITY DEFINER on
-- purpose: the reveal policy below queries prompt_answers, and a policy that
-- reads its OWN table directly recurses infinitely. Going through a definer
-- function breaks the cycle.
create or replace function public.has_answered(ua uuid, ub uuid, d date)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.prompt_answers
     where user_a = ua and user_b = ub and on_date = d and responder = auth.uid());
$$;
revoke all on function public.has_answered(uuid, uuid, date) from public;
grant execute on function public.has_answered(uuid, uuid, date) to authenticated;

alter table public.prompt_answers enable row level security;

-- Your own answer always. Theirs ONLY once you've answered that day.
drop policy if exists prompt_read on public.prompt_answers;
create policy prompt_read on public.prompt_answers
  for select to authenticated using (
    auth.uid() in (user_a, user_b)
    and (
      responder = auth.uid()
      or public.has_answered(user_a, user_b, on_date)
    )
  );

-- You may only write your OWN answer, into a pair you belong to, dated today.
-- No UPDATE grant below: an answer is final once written, which is what makes
-- the simultaneous reveal mean anything.
drop policy if exists prompt_write on public.prompt_answers;
create policy prompt_write on public.prompt_answers
  for insert to authenticated
  with check (
    responder = auth.uid()
    and auth.uid() in (user_a, user_b)
    and array[user_a, user_b] = public.pair_key(user_a, user_b)
    and on_date = public.ist_date()
  );

grant select, insert on public.prompt_answers to authenticated;

-- Today's prompt, chosen deterministically from the day number so both people
-- (and every pair) see the same question without storing a schedule.
create or replace function public.todays_prompt()
returns table (id int, body text)
language sql stable security definer set search_path = public as $$
  select p.id, p.body
    from public.prompts p
   where p.id = (
     (extract(epoch from public.ist_date())::bigint / 86400)
       % (select count(*) from public.prompts)
   ) + 1;
$$;
revoke all on function public.todays_prompt() from public;
grant execute on function public.todays_prompt() to authenticated;

-- Whether the OTHER person has answered today, without leaking what they said.
-- Lets the UI say "they're waiting on you" before the reveal.
create or replace function public.prompt_status(other uuid)
returns json language sql stable security definer set search_path = public as $$
  with pk as (select least(auth.uid(), other) ua, greatest(auth.uid(), other) ub)
  select json_build_object(
    'mine_done',   exists (select 1 from public.prompt_answers a, pk
                            where a.user_a = pk.ua and a.user_b = pk.ub
                              and a.on_date = public.ist_date() and a.responder = auth.uid()),
    'theirs_done', exists (select 1 from public.prompt_answers a, pk
                            where a.user_a = pk.ua and a.user_b = pk.ub
                              and a.on_date = public.ist_date() and a.responder = other)
  );
$$;
revoke all on function public.prompt_status(uuid) from public;
grant execute on function public.prompt_status(uuid) to authenticated;

notify pgrst, 'reload schema';
select 'together: birthdays, status notes, question of the day' as status;

commit;
